<?php require '../config.php'; deviceAuth();$order=trim($_POST['order_id']??'');$p=db();$p->beginTransaction();try{$s=$p->prepare("SELECT * FROM orders WHERE order_id=? FOR UPDATE");$s->execute([$order]);$o=$s->fetch();if(!$o||$o['status']!=='DELIVERED')throw new Exception('Invalid order');$p->prepare("UPDATE orders SET status='CLAIMED',claimed_at=NOW() WHERE order_id=?")->execute([$order]);$p->prepare("UPDATE lockers SET status='AVAILABLE' WHERE id=?")->execute([$o['locker_id']]);$p->prepare("INSERT INTO events(order_id,event_type,details) VALUES(?,'CLAIMED','Customer picked up order')")->execute([$order]);$p->commit();jsonOut(['ok'=>true]);}catch(Throwable $e){$p->rollBack();jsonOut(['ok'=>false,'error'=>$e->getMessage()],409);}
